/**
 * Runtime configuration (Lambda environment) and the chat secret.
 *
 * The secret (merch-os/<env>/support-chat) holds JSON:
 *   { "visitorTokenSecret": "...", "vapidPublicKey": "...", "vapidPrivateKey": "..." }
 * visitorTokenSecret is generated by CloudFormation; the VAPID pair is added by
 * services/support-chat/scripts/init-vapid.mjs. Values never go in env vars.
 */

import { GetSecretValueCommand, SecretsManagerClient } from '@aws-sdk/client-secrets-manager';

export interface ChatSecret {
  visitorTokenSecret: string;
  vapidPublicKey?: string | undefined;
  vapidPrivateKey?: string | undefined;
}

function required(name: string): string {
  const value = process.env[name];
  if (!value) throw new Error(`${name} is not configured`);
  return value;
}

export const config = {
  get table(): string {
    return required('CHAT_TABLE');
  },
  get secretArn(): string {
    return required('CHAT_SECRET_ARN');
  },
  /** https://… management endpoint of the WebSocket stage. */
  get wsCallbackUrl(): string {
    return required('WS_CALLBACK_URL');
  },
  /** Name shown to visitors once a person joins. */
  get agentDisplayName(): string {
    return process.env['AGENT_DISPLAY_NAME'] || 'Imani';
  },
  /** Where alert emails go. */
  get supportEmail(): string {
    return process.env['SUPPORT_EMAIL'] || 'info@merchos.co.za';
  },
  get fromEmail(): string {
    return process.env['CHAT_FROM_EMAIL'] || 'MerchOS Chat <chat@merchos.co.za>';
  },
  get adminBaseUrl(): string {
    return (process.env['ADMIN_BASE_URL'] || 'https://admin.merchos.co.za').replace(/\/$/, '');
  },
  get visitorOrigins(): string[] {
    return (process.env['VISITOR_ORIGINS'] ?? '').split(',').filter(Boolean);
  },
  get agentOrigins(): string[] {
    return (process.env['AGENT_ORIGINS'] ?? '').split(',').filter(Boolean);
  },
  get userPoolId(): string {
    return required('USER_POOL_ID');
  },
  get adminClientId(): string {
    return required('ADMIN_CLIENT_ID');
  },
  get timerFunctionArn(): string {
    return required('TIMER_FUNCTION_ARN');
  },
  get schedulerRoleArn(): string {
    return required('SCHEDULER_ROLE_ARN');
  },
  get scheduleGroup(): string {
    return required('SCHEDULE_GROUP');
  },
};

let secretsClient: SecretsManagerClient | undefined;
let cachedSecret: { value: ChatSecret; at: number } | undefined;
/** Re-read occasionally so a rotated/added VAPID key is picked up without a deploy. */
const SECRET_CACHE_MS = 5 * 60 * 1000;

export async function getChatSecret(): Promise<ChatSecret> {
  if (cachedSecret && Date.now() - cachedSecret.at < SECRET_CACHE_MS) return cachedSecret.value;
  secretsClient ??= new SecretsManagerClient({});
  const out = await secretsClient.send(new GetSecretValueCommand({ SecretId: config.secretArn }));
  const parsed = JSON.parse(out.SecretString ?? '{}') as Partial<ChatSecret>;
  if (!parsed.visitorTokenSecret) throw new Error('Chat secret has no visitorTokenSecret');
  const value: ChatSecret = {
    visitorTokenSecret: parsed.visitorTokenSecret,
    vapidPublicKey: parsed.vapidPublicKey,
    vapidPrivateKey: parsed.vapidPrivateKey,
  };
  cachedSecret = { value, at: Date.now() };
  return value;
}

/** @internal tests only */
export function _resetSecretCache(): void {
  cachedSecret = undefined;
}
